// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { DemoStage, Label, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, FLAME, HOOKS, PROPS, SELECTED, TREE } from './script'

const ROW = 26
const INDENT = 16
const TABS = ['Components', 'Profiler', 'Suspense']

const parentOf = (index: number) => {
  for (let i = index - 1; i >= 0; i -= 1) if (TREE[i].depth === TREE[index].depth - 1) return i
  return -1
}

const build: Build = ({ tl, q, qa, step, final, move, click, scramble, wait, cursorOut }) => {
  const tab = (index: number) => {
    move(`tab-${index}`)
    click(`tab-${index}`)
    tl.to(qa('tab'), { color: '#8b8b9a', borderColor: 'rgba(99,102,241,0)', duration: 0.15 }, '<')
    tl.to(
      q(`tab-${index}`),
      { color: '#f4f4f6', borderColor: 'rgba(99,102,241,1)', duration: 0.15 },
      '<',
    )
    tl.to(qa('pane'), { opacity: 0, duration: 0.2 }, '<')
    tl.to(q(`pane-${index}`), { opacity: 1, duration: 0.3 }, '<0.1')
  }

  step(0)
  tl.fromTo(
    qa('node'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.1 },
    0.3,
  )
  tl.fromTo(
    qa('link'),
    { drawSVG: '0%' },
    { drawSVG: '100%', duration: 0.35, stagger: 0.1, ease: 'power2.out' },
    0.4,
  )

  step(1, '+=0.3')
  move(`node-${SELECTED}`, { ax: 0.3 })
  click(`node-${SELECTED}`)
  tl.to(q(`node-${SELECTED}`), { backgroundColor: 'rgba(99,102,241,0.25)', duration: 0.2 }, '<')
  tl.fromTo(
    q('pulse'),
    { scale: 0.6, opacity: 0.8 },
    { scale: 1.6, opacity: 0, duration: 0.7 },
    '<',
  )
  tl.to(q('inspect'), { opacity: 1, duration: 0.25 }, '<')
  qa('prop-value').forEach((element, index) =>
    scramble(element, element.dataset.value ?? '', {
      at: index === 0 ? '<0.1' : '<0.08',
      duration: 0.5,
      chars: '0123456789{}',
    }),
  )

  step(2, '+=0.5')
  tab(1)
  tl.fromTo(
    qa('flame'),
    { scaleX: 0 },
    { scaleX: 1, duration: 0.5, stagger: 0.08, ease: 'expo.out' },
  )
  tl.fromTo(q('storm'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '-=0.1')
  tl.to(
    qa('hot'),
    { backgroundColor: 'rgba(251,113,133,0.75)', duration: 0.25, yoyo: true, repeat: 3 },
    '<',
  )

  step(3, '+=0.5')
  tab(2)
  cursorOut('<0.3')
  qa('boundary').forEach((element, index) => {
    tl.to(
      element.querySelector('[data-d~="state"]'),
      { text: 'resolved', color: '#34d399', duration: 0.3 },
      `+=${index === 0 ? 0.5 : 0.35}`,
    )
    tl.to(
      element.querySelector('[data-d~="spinner"]'),
      { opacity: 0, scale: 0, duration: 0.2 },
      '<',
    )
  })
  final('+=0.3')
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="React DevTools showing a component tree, its props, a profiler flame chart and Suspense boundaries"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <div className="flex gap-4 border-b border-line text-[11px]">
            {TABS.map((name, index) => (
              <span
                key={name}
                data-d={`tab tab-${index}`}
                className="border-b-2 pb-1.5"
                style={{
                  color: index === 0 ? '#f4f4f6' : '#8b8b9a',
                  borderColor: index === 0 ? '#6366f1' : 'transparent',
                }}
              >
                {name}
              </span>
            ))}
          </div>
          <div className="relative min-h-0 flex-1">
            <div data-d="pane pane-0" className="absolute inset-0 grid grid-cols-[1fr_170px] gap-2">
              <div className="relative rounded-xl border border-line bg-canvas/70 p-2 font-mono text-[11px]">
                <svg
                  className="pointer-events-none absolute left-2 top-2 overflow-visible"
                  width="200"
                  height={TREE.length * ROW}
                >
                  {TREE.map((node, index) => {
                    const parent = parentOf(index)
                    if (parent < 0) return null
                    const px = TREE[parent].depth * INDENT + 6
                    return (
                      <path
                        key={index}
                        data-d="link"
                        d={`M ${px} ${parent * ROW + 20} V ${index * ROW + 13} H ${node.depth * INDENT + 2}`}
                        fill="none"
                        stroke="rgba(99,102,241,0.55)"
                        strokeWidth="1.2"
                      />
                    )
                  })}
                </svg>
                {TREE.map((node, index) => (
                  <p
                    key={index}
                    data-d={`node node-${index}`}
                    className="relative flex h-[26px] items-center gap-1.5 rounded-md pr-2"
                    style={{ marginLeft: node.depth * INDENT + 4, paddingLeft: 6 }}
                  >
                    {index === SELECTED ? (
                      <span
                        data-d="pulse"
                        className="absolute inset-0 rounded-md border border-[#6366f1] opacity-0"
                      />
                    ) : null}
                    <span className="text-[#c4b5fd]">{node.name}</span>
                    {node.note ? (
                      <span className="text-[9.5px] text-muted">{node.note}</span>
                    ) : null}
                  </p>
                ))}
              </div>
              <div
                data-d="inspect"
                className="space-y-1.5 rounded-xl border border-line bg-canvas/70 p-2.5 font-mono text-[10px] opacity-0"
              >
                <p className="text-[11px] text-[#c4b5fd]">CartItem</p>
                <Label>props</Label>
                {PROPS.map(([key, value]) => (
                  <p key={key} className="truncate">
                    <span className="text-[#93c5fd]">{key}</span>:{' '}
                    <span data-d="prop-value" data-value={value} className="text-amber" />
                  </p>
                ))}
                <Label className="pt-1">hooks</Label>
                {HOOKS.map(([key, value]) => (
                  <p key={key}>
                    <span className="text-muted">{key}</span>:{' '}
                    <span data-d="prop-value" data-value={value} className="text-emerald" />
                  </p>
                ))}
              </div>
            </div>
            <div
              data-d="pane pane-1"
              className="absolute inset-0 rounded-xl border border-line bg-canvas/70 p-3 opacity-0"
            >
              <Label>Commit 3 of 3 · 18.4 ms</Label>
              <div className="mt-2 space-y-1.5">
                {FLAME.map((bar) => (
                  <div key={bar.name} style={{ marginLeft: `${bar.depth * 4}%` }}>
                    <span
                      data-d={bar.hot ? 'flame hot' : 'flame'}
                      className="flex h-6 origin-left items-center rounded px-2 font-mono text-[10px] text-canvas"
                      style={{
                        width: `${bar.width - bar.depth * 4}%`,
                        background: bar.hot ? 'rgba(251,191,36,0.85)' : 'rgba(99,102,241,0.7)',
                      }}
                    >
                      {bar.name}
                    </span>
                  </div>
                ))}
              </div>
              <p
                data-d="storm"
                className="mt-3 inline-flex rounded-full bg-rose/15 px-2.5 py-1 font-mono text-[10px] text-rose opacity-0"
              >
                CartItem rendered 14× in this interaction
              </p>
            </div>
            <div
              data-d="pane pane-2"
              className="absolute inset-0 space-y-2 rounded-xl border border-line bg-canvas/70 p-3 font-mono text-[11px] opacity-0"
            >
              {['Reviews', 'Recommendations', 'Shipping estimate'].map((name) => (
                <div
                  key={name}
                  data-d="boundary"
                  className="flex items-center gap-2 rounded-lg border border-line px-2.5 py-2"
                >
                  <span
                    data-d="spinner"
                    className="size-2.5 rounded-full border-2 border-amber border-t-transparent"
                  />
                  <span className="text-[#c4b5fd]">&lt;Suspense&gt;</span>
                  <span className="text-ink-soft">{name}</span>
                  <span data-d="state" className="ml-auto text-amber">
                    pending
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
